import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()

# Parse all grids - find LAST occurrences only
t_clean = t.replace('\\n', '\n')
marker_pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):'
matches = list(re.finditer(marker_pattern, t_clean))

last_demo_inputs = []
last_demo_outputs = []
last_test_input = None

for m in matches:
    parts = m.group(1).split()
    dims = [int(m.group(2)), int(m.group(3))]

    if 'Demo pair' in m.group(1):
        key = f"{dims[0]}x{dims[1]}"
        if key == "17x19":
            last_demo_inputs.append(m)
            last_demo_outputs.append(m)
    elif 'Test input' in m.group(1):
        # Only keep the last one (most recent)
        last_test_input = m

grids = {}

def parse_grid_from_match(match):
    """Parse grid lines after a marker match"""
    start = match.end()
    # Look ahead to find end of this section
    text_after = t_clean[start:start+5000]

    # Find the next section marker
    next_marker_match = re.search(r'\{(?:["\']type["\']:|"\'type\':)', text_after)
    if next_marker_match:
        end = start + next_marker_match.start()
    else:
        end = min(start + 2000, len(t_clean))

    lines = []
    for i in range(start, end):
        line = t_clean[i:i+200].strip()
        # Check if it's a grid data line (numbers separated by spaces or brackets)
        if line and (re.match(r'^\d+', line) or re.match(r'^\[', line)):
            lines.append(line)
            if re.match(r'^\d+', line) and not line.startswith('0 '):
                continue  # Might be a header

    # Better approach: read lines until we hit something that looks like JSON
    for i in range(start, min(start + 3000, len(t_clean))):
        chunk = t_clean[i:i+20]
        if chunk.startswith('{'):
            break
        line = t_clean[i:i+100].rstrip('\n')
        if re.match(r'^[\d\s\-,\[\]]+$', line.strip()):
            lines.append(line)

    return [[int(x) for x in re.findall(r'-?\d+', line)] for line in lines if any(c.isdigit() or c=='-' for c in line.split()[:3])]

if last_demo_inputs:
    m = last_demo_inputs[-1]
    grids["demo_1_in"] = parse_grid_from_match(m)

if last_demo_outputs:
    m = last_demo_outputs[-1]
    grids["demo_1_out"] = parse_grid_from_match(m)

if last_test_input:
    m = last_test_input[-1] if isinstance(last_test_input, list) else last_test_input
